 if type(d.talentDefinitions)=="table" then
  local valid={}
  for _,def in ipairs(d.talentDefinitions) do
   if not (def.key and d.deprecatedTalentKeys[def.key]) then valid[#valid+1]=def end
  end
  d.talentDefinitions=valid
 end
 if type(d.talents)=="table" then
  for key,_ in pairs(d.deprecatedTalentKeys) do d.talents[key]=nil end
 end
 -- Previous Improved Serpent Sting modifiers are Classic-only.
 if type(d.modifiers)=="table" then
  local valid={}
  for _,m in ipairs(d.modifiers) do
   if m.talent~="improvedSerpentSting" then valid[#valid+1]=m end
  end
  d.modifiers=valid
 end
 -- Aimed Shot MUST stay in d.abilities and d.spellAliases: it is baseline from level 20.
 d.talentTreeByKey={}
 local defs={}
 for _,def in ipairs(d.talentDefinitions or {})do if type(def.key)=="string"then defs[def.key]=def end end
 for _,tree in ipairs(d.talentTrees) do
  for _,node in ipairs(tree.talents) do
   node.treeId=tree.id;node.treeName=tree.name;node.treeIndex=tree.index
   local def=defs[node.key]
   node.modelAvailable=(def~=nil)
   node.supported=def and def.supported
   node.source=def and def.source or d.talentTreeSource
   d.talentTreeByKey[node.key]=node
  end
 end
 d.unplacedTalentDefinitions={}
end
-- END FUS-UNIFIED-TALENT-TREES

-- Deadly Aspects (Forever beta 1.60.1.70338, https://foreverdb.net/spell/19552):
-- with Aspect of the Hawk, Auto Shot has a 2% chance per rank to increase ranged attack
-- speed by 30% for 12 sec; with Aspect of the Beast the same applies to melee auto attacks.
do
 local d=FUSLiveData["hunter"]
 d.genericProcs=d.genericProcs or {}
 local source='https://foreverdb.net/spell/19552'
 table.insert(d.genericProcs,{key='deadlyAspectsRanged',talent='deadlyAspects',sources={'auto:ranged'},chanceValues={0.02,0.04,0.06,0.08,0.10},
  duration=12,rangedHasteValues={0.3,0.3,0.3,0.3,0.3},requiresAuraNames={'aspect of the hawk','aspekt des falken'},source=source})
 table.insert(d.genericProcs,{key='deadlyAspectsMelee',talent='deadlyAspects',sources={'auto:mainhand'},meleeOnly=true,chanceValues={0.02,0.04,0.06,0.08,0.10},
  duration=12,attackHasteValues={0.3,0.3,0.3,0.3,0.3},requiresAuraNames={'aspect of the beast','aspekt des wildtiers'},source=source})
end
